<template>
  <!--
    v5 splits the old overlay Sidebar in two: `Sidebar` is now a layout element that
    paints no mask of its own. The mask and the click-outside-to-dismiss behaviour live
    in `SidebarBackdrop`, which reaches both through the `SidebarLayout` it is nested in,
    and finds this sidebar there only because the sidebar carries an `id` to register
    under.
  -->
  <SidebarLayout>
    <SidebarBackdrop />
    <Sidebar
      id="customize"
      v-model:open="VisibleSidebar"
      side="right"
      overlay
      collapsible="offcanvas"
      width="500px"
      :pt="{
        root: {
          style: { maxWidth: '100vw' }
        },
        header: {
          class: 'justify-content-between pb-0'
        }
      }"
    >
      <h2 class="flex mb-2 flex-row align-items-center justify-content-between">
        <span><i class="pi pi-palette"></i> Customize</span>
        <Button
          icon="pi pi-times"
          severity="secondary"
          rounded
          text
          aria-label="Close"
          :pt="{
            root: { style: { width: '2rem', height: '2rem', color: 'rgba(255, 255, 255, 0.6)' } }
          }"
          @click="VisibleSidebar = false"
        />
      </h2>
      <Tabs v-model:value="activeTab">
        <TabList>
          <Tab value="items">📋 Items</Tab>
          <Tab value="settings">⚙️ Settings</Tab>
        </TabList>
        <TabPanels>
          <TabPanel value="items">
            <div class="col-12">
              <label for="dd-group" class="block mb-2">Select a Group</label>
              <InputGroup>
                <Button
                  icon="pi pi-trash"
                  severity="danger"
                  outlined
                  aria-label="Remove group"
                  @click="removeGroup"
                  tabindex="-1"
                />
                <Select
                  :model-value="GroupLabel"
                  inputId="dd-group"
                  :options="GroupLabels"
                  @update:model-value="itemService.changeGroupLabel"
                />
                <Button
                  icon="pi pi-pencil"
                  severity="info"
                  outlined
                  aria-label="Rename group"
                  @click="showRenameGroupDialog = true"
                />
                <Button
                  icon="pi pi-plus"
                  severity="success"
                  outlined
                  aria-label="Add group"
                  @click="showAddGroupDialog = true"
                />
              </InputGroup>
            </div>
            <Divider />
            <InputGroup class="col-12">
              <ToggleButton
                :modelValue="bulkEditMode"
                @change="toggleBulkEditMode"
                class="w-full border-round"
                onLabel="Save"
                offLabel="Bulk Edit"
                onIcon="pi pi-check"
                offIcon="pi pi-pencil"
              />
            </InputGroup>
            <template v-if="!bulkEditMode">
              <div
                v-focustrap="{
                  disabled: Items?.length === 0
                }"
              >
                <ItemInputGroup
                  :class="['col-12']"
                  v-for="item in Items"
                  :key="item._id"
                  :modelValue="item"
                  :autoFocus="item._id === newItemId"
                ></ItemInputGroup>
              </div>
              <InputGroup class="col-12">
                <Button
                  ref="addButton"
                  class="w-full"
                  icon="pi pi-plus"
                  severity="success"
                  outlined
                  aria-label="Add item"
                  @click="addItem"
                />
              </InputGroup>
            </template>
            <div v-else class="m-2">
              <Textarea v-model="textArea" />
              <small class="text-color-secondary"
                >This feature uses
                <a
                  href="https://en.wikipedia.org/wiki/Comma-separated_values#Basic_rules"
                  target="_blank"
                  rel="noopener"
                  >the CSV syntax</a
                >
                with two columns.</small
              >
            </div>
          </TabPanel>
          <TabPanel value="settings">
            <div v-focustrap>
              <div class="col-12">
                <label for="in-pageTitle" class="block mb-2">Page Title</label>
                <InputText id="in-pageTitle" v-model="PageTitle" class="w-full" />
              </div>
              <div class="col-12">
                <label for="in-pageDesc" class="block mb-2">Page Description</label>
                <InputText id="in-pageDesc" v-model="PageDescription" class="w-full" />
              </div>
              <div class="col-12">
                <label for="dd-sound" class="block mb-2">Select a Ticking Sound</label>
                <div class="grid">
                  <div class="col-8">
                    <Select
                      v-model="TickSound"
                      inputId="dd-sound"
                      :options="TickSounds"
                      optionLabel="label"
                      optionGroupLabel="label"
                      optionGroupChildren="items"
                      class="w-full"
                    />
                  </div>
                  <div class="col-4">
                    <FileUpload
                      mode="basic"
                      accept="audio/*,.webm"
                      customUpload
                      auto
                      @uploader="customBase64Uploader($event, 'TickSound')"
                      :pt="{
                        chooseButton: {
                          class: 'w-full'
                        }
                      }"
                    />
                  </div>
                </div>
              </div>
              <div class="col-12">
                <label for="dd-sound" class="block mb-2">Select a Congratulatory Sound</label>
                <div class="grid">
                  <div class="col-8">
                    <Select
                      v-model="CongratulationSound"
                      inputId="dd-sound"
                      :options="CongratulationSounds"
                      optionLabel="label"
                      optionGroupLabel="label"
                      optionGroupChildren="items"
                      class="w-full"
                    />
                  </div>
                  <div class="col-4">
                    <FileUpload
                      mode="basic"
                      accept="audio/*,.webm"
                      customUpload
                      auto
                      @uploader="customBase64Uploader($event, 'CongratulationSound')"
                      :pt="{
                        chooseButton: {
                          class: 'w-full'
                        }
                      }"
                    />
                  </div>
                </div>
              </div>
              <div class="col-12">
                <label for="sl-labelLength" class="block mb-2">Item Label Length</label>
                <Slider
                  v-model="LabelLength"
                  inputId="sl-labelLength"
                  :min="0.3"
                  :max="0.75"
                  :step="0.01"
                />
              </div>
              <div class="col-12">
                <label for="sl-labelLength" class="block mb-2">Fair mode</label>
                <ToggleButton
                  v-model="Fairmode"
                  @change="
                    () => {
                      itemService.syncItems();
                    }
                  "
                  :pt="{
                    root: {
                      class: 'w-full'
                    }
                  }"
                />
              </div>
              <div class="col-12">
                <label for="btn-fullscreen" class="block mb-2">Fullscreen</label>
                <ToggleButton
                  v-model="isFullscreen"
                  @change="toggleFullscreen"
                  onLabel="Exit Fullscreen"
                  offLabel="Enter Fullscreen"
                  onIcon="pi pi-window-minimize"
                  offIcon="pi pi-window-maximize"
                  :pt="{
                    root: {
                      class: 'w-full'
                    }
                  }"
                />
              </div>
            </div>
          </TabPanel>
        </TabPanels>
      </Tabs>

      <Dialog v-model:visible="showRenameGroupDialog" modal dismissableMask header="Header">
        <template #container>
          <form class="surface-card border-round shadow-2 p-4 max-w-screen" @submit.prevent>
            <div class="text-900 font-medium mb-2 text-xl">Rename Group</div>
            <p class="min-w-min text-color-secondary">Change the name, change your luck.</p>
            <div class="flex mb-4 flex-column lg:flex-row">
              <IconField class="w-full">
                <InputIcon class="pi pi-pencil" />
                <InputText
                  autofocus
                  v-model="renameGroupName"
                  placeholder="New Group Name"
                  :pt="{
                    root: { class: 'w-full' }
                  }"
                />
              </IconField>
            </div>
            <Button
              type="submit"
              class="confirm-button"
              icon="pi pi-check"
              label="Ok"
              severity="success"
              @click="renameGroup"
            ></Button>
          </form>
        </template>
      </Dialog>
      <Dialog v-model:visible="showAddGroupDialog" modal dismissableMask header="Header">
        <template #container>
          <form class="surface-card border-round shadow-2 p-4 max-w-screen" @submit.prevent>
            <div class="text-900 font-medium mb-2 text-xl">Add Group</div>
            <p class="min-w-min text-color-secondary">What should we name this new spinner?</p>
            <div class="flex mb-4 flex-column lg:flex-row">
              <IconField class="w-full">
                <InputIcon class="pi pi-plus" />
                <InputText
                  autofocus
                  v-model="addGroupName"
                  placeholder="New Group Name"
                  :pt="{
                    root: { class: 'w-full' }
                  }"
                />
              </IconField>
            </div>
            <Button
              type="submit"
              class="confirm-button"
              icon="pi pi-check"
              label="Ok"
              severity="success"
              @click="addGroup"
            ></Button>
          </form>
        </template>
      </Dialog>
    </Sidebar>
  </SidebarLayout>
</template>

<script setup lang="ts">
import { inject, nextTick, onMounted, onUnmounted, ref, watch } from 'vue';
import type { FileUploadUploaderEvent } from 'primevue/fileupload';
import { useConfirm } from 'primevue/useconfirm';
import { useToast } from 'primevue/usetoast';
import { ItemService, GroupLabel, GroupLabels, Items } from '@/services/ItemService';
import { VisibleSidebar } from '@/services/SidebarService';
import {
  TickSound,
  TickSounds,
  LabelLength,
  CongratulationSound,
  CongratulationSounds,
  Fairmode
} from '@/services/SettingService';
import { PageTitle, PageDescription } from '@/services/PageService';
import ItemInputGroup from '@/components/sidebar-panel/ItemInputGroup.vue';
import type { IItem } from '@/interface/IItem';
import { StringHelper } from '@/helpers/StringHelper';

const itemService = inject<ItemService>('ItemService')!;
const toast = useToast();

const addButton = ref();
const confirm = useConfirm();
const bulkEditMode = ref(false);
const textArea = ref('');
const activeTab = ref<'items' | 'settings'>('items');

// v3's Sidebar closed itself on Escape. v5's Sidebar handles no keyboard at all and
// SidebarLayout adds none, so the listener lives here; it is bound only while the panel
// is open, the way Drawer does it.
//
// The `isComposing` guard is for IME input: Escape cancels a composition in progress,
// and that keystroke must not also close the panel being typed into.
const onKeydown = (event: KeyboardEvent) => {
  if (event.code === 'Escape' && !event.isComposing) VisibleSidebar.value = false;
};

watch(VisibleSidebar, (visible) => {
  if (visible) document.addEventListener('keydown', onKeydown);
  else document.removeEventListener('keydown', onKeydown);
});

onUnmounted(() => {
  document.removeEventListener('keydown', onKeydown);
  document.removeEventListener('fullscreenchange', handleFullscreenChange);
});

// The id of the item added last, so that ItemInputGroup can tell the one the
// user just created from the ones that were already there. Cleared once it has
// been rendered, so the item does not claim focus again on a later re-render.
const newItemId = ref<string>();

async function addItem() {
  const { id } = await itemService.addItem();
  newItemId.value = id;
  await nextTick();
  newItemId.value = undefined;

  setTimeout(() => {
    addButton.value.$el.scrollIntoView({ behavior: 'smooth' });
  }, 100);
}

const removeGroup = ($event: Event) => {
  if ($event.target instanceof HTMLElement)
    confirm.require({
      target: $event.target || undefined,
      message: 'Are you sure you want to delete this group?',
      icon: 'pi pi-exclamation-triangle text-yellow-400',
      accept: async () => {
        await itemService.removeGroup(GroupLabel.value!);
      }
    });
};

const showRenameGroupDialog = ref(false);
const renameGroupName = ref(GroupLabel.value);
const renameGroup = async () => {
  await itemService.renameGroup(GroupLabel.value!, renameGroupName.value!);
  showRenameGroupDialog.value = false;
};

const showAddGroupDialog = ref(false);
const addGroupName = ref('');
const addGroup = async () => {
  await itemService.changeGroupLabel(addGroupName.value);
  await itemService.addItem();
  GroupLabels.value = await itemService.getGroupLabels();
  showAddGroupDialog.value = false;
  addGroupName.value = '';
};

const customBase64Uploader = async (
  event: FileUploadUploaderEvent,
  mode: 'TickSound' | 'CongratulationSound'
) => {
  const file = Array.isArray(event.files) ? event.files[0] : event.files;
  const reader = new FileReader();
  const blob = await fetch(window.URL.createObjectURL(file)).then((r) => r.blob()); //blob:url

  reader.readAsDataURL(blob);

  reader.onloadend = function () {
    const base64data = reader.result;
    console.debug('Sound uploaded', base64data);
    if (mode === 'TickSound') {
      TickSound.value = {
        label: file.name,
        value: base64data as string
      };
    } else if (mode === 'CongratulationSound') {
      CongratulationSound.value = {
        label: file.name,
        value: base64data as string
      };
    }
  };
};

const toggleBulkEditMode = async ($event: Event) => {
  if (!bulkEditMode.value && Fairmode.value && $event.target instanceof HTMLElement) {
    confirm.require({
      target: $event.target || undefined,
      message: 'The item weights will be LOST if you perform bulk edits in fair mode!',
      icon: 'pi pi-exclamation-triangle text-yellow-400',
      defaultFocus: 'reject',
      accept: async () => {
        bulkEditMode.value = true;
        await changeBulkEditMode();
      },
      reject: () => {
        bulkEditMode.value = false;
      }
    });
  } else {
    bulkEditMode.value = !bulkEditMode.value;
    await changeBulkEditMode();
  }
};

const changeBulkEditMode = async () => {
  if (bulkEditMode.value) {
    textArea.value = badCSV ?? StringHelper.csvStringify();
    badCSV = undefined;
    console.debug('Bulk edit mode on');
  } else {
    console.debug('Bulk edit mode off');

    let items: IItem[] = [];
    try {
      items = StringHelper.csvParse(textArea.value, true).map(({ label, weight }) => ({
        label: label,
        weight: +weight < 1 ? 1 : +weight,
        group: GroupLabel.value!,
        order: -1
      }));
      toast.removeAllGroups();
    } catch (error) {
      const e = error as Error;
      console.error('Error parsing items from textarea', e);
      toast.add({
        severity: 'error',
        summary: 'CSV parsed failed!',
        detail: e.message
      });

      badCSV = textArea.value;
      bulkEditMode.value = true;
      return;
    }
    console.debug('Items parsed from textarea', items);

    await itemService.cleanUpGroup(GroupLabel.value!);
    await itemService.addItems(items);
  }
};

const isFullscreen = ref(false);

const toggleFullscreen = async () => {
  if (!document.fullscreenElement) {
    await document.documentElement.requestFullscreen().catch(() => {});
  } else if (document.exitFullscreen) {
    await document.exitFullscreen();
  }
};

const handleFullscreenChange = () => {
  isFullscreen.value = !!document.fullscreenElement;
};

let badCSV: string | undefined = undefined;
onMounted(() => {
  isFullscreen.value = !!document.fullscreenElement;
  document.addEventListener('fullscreenchange', handleFullscreenChange);

  watch(GroupLabel, () => {
    renameGroupName.value = GroupLabel.value;
  });
});
</script>

<style scoped>
.confirm-button {
  float: right;
}

textarea {
  width: -webkit-fill-available;
  resize: vertical;
  min-height: 50vh;
  font-size: larger;
}

h2 {
  font-weight: 400;
}
</style>
